"""Script to generate tar.gz test fixture repos."""
from __future__ import annotations

import io
import os
import tarfile


def _add_text(tf: tarfile.TarFile, name: str, content: str, mode: int = 0o644) -> None:
    data = content.encode("utf-8")
    info = tarfile.TarInfo(name=name)
    info.size = len(data)
    info.mode = mode
    tf.addfile(info, io.BytesIO(data))


def _add_dir(tf: tarfile.TarFile, name: str) -> None:
    info = tarfile.TarInfo(name=name)
    info.type = tarfile.DIRTYPE
    info.mode = 0o755
    tf.addfile(info, io.BytesIO(b""))


def make_clean_repo() -> bytes:
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tf:
        _add_dir(tf, "myproject")
        _add_dir(tf, "myproject/src")
        _add_dir(tf, "myproject/tests")
        _add_text(tf, "myproject/README.md",
                  "# My Project\n\nA clean Python project.\n\n## Installation\n\npip install -e .\n")
        _add_text(tf, "myproject/LICENSE", "MIT License\n(c) 2024")
        _add_text(tf, "myproject/.gitignore",
                  "__pycache__/\n*.pyc\n.env\n.venv/\n")
        _add_text(tf, "myproject/pyproject.toml",
                  '[project]\nname = "myproject"\nversion = "0.1.0"\nlicense = {text = "MIT"}\n')
        _add_text(tf, "myproject/src/__init__.py", "")
        _add_text(tf, "myproject/src/main.py",
                  'def main():\n    print("hello")\n\nif __name__ == "__main__":\n    main()\n')
        _add_text(tf, "myproject/tests/__init__.py", "")
        _add_text(tf, "myproject/tests/test_main.py",
                  'from src.main import main\n\ndef test_main():\n    main()\n')
    return buf.getvalue()


def make_no_tests_repo() -> bytes:
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tf:
        _add_dir(tf, "notest")
        _add_dir(tf, "notest/src")
        _add_text(tf, "notest/README.md",
                  "# No Tests\n\nA project with no tests.\n")
        _add_text(tf, "notest/LICENSE", "MIT License\n")
        _add_text(tf, "notest/.gitignore", "__pycache__/\n")
        _add_text(tf, "notest/pyproject.toml",
                  '[project]\nname = "notest"\nversion = "0.1.0"\n')
        _add_text(tf, "notest/src/__init__.py", "")
        _add_text(tf, "notest/src/app.py",
                  'def do_thing():\n    return 42\n')
    return buf.getvalue()


def make_js_repo() -> bytes:
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tf:
        _add_dir(tf, "jsapp")
        _add_dir(tf, "jsapp/src")
        _add_dir(tf, "jsapp/tests")
        _add_dir(tf, "jsapp/.github/workflows")
        _add_text(tf, "jsapp/README.md",
                  "# JS App\n\nA JavaScript project.\n\n## Getting Started\n\nnpm install\n")
        _add_text(tf, "jsapp/LICENSE", "MIT License\n")
        _add_text(tf, "jsapp/.gitignore", "node_modules/\n.env\n")
        _add_text(tf, "jsapp/package.json",
                  '{\n  "name": "jsapp",\n  "version": "0.1.0",\n'
                  '  "scripts": {\n    "start": "node src/index.js",\n'
                  '    "test": "jest"\n  },\n'
                  '  "license": "MIT"\n}\n')
        _add_text(tf, "jsapp/package-lock.json",
                  '{"name": "jsapp", "version": "0.1.0", "lockfileVersion": 3}\n')
        _add_text(tf, "jsapp/src/index.js",
                  'function greet(name) {\n  return `Hello, ${name}!`;\n}\n\nmodule.exports = { greet };\n')
        _add_text(tf, "jsapp/tests/index.test.js",
                  'const { greet } = require("../src/index.js");\n\ntest("greet", () => {\n  expect(greet("world")).toBe("Hello, world!");\n});\n')
        _add_text(tf, "jsapp/.github/workflows/ci.yml",
                  "name: CI\non: [push]\njobs:\n  test:\n    runs-on: ubuntu-latest\n")
    return buf.getvalue()


def make_generated_repo() -> bytes:
    buf = io.BytesIO()
    with tarfile.open(fileobj=buf, mode="w:gz") as tf:
        _add_dir(tf, "genrepo")
        _add_dir(tf, "genrepo/src")
        _add_text(tf, "genrepo/README.md",
                  "# Generated Repo\n\nContains auto-generated files.\n")
        _add_text(tf, "genrepo/LICENSE", "MIT License\n")
        _add_text(tf, "genrepo/.gitignore", "*.pyc\n")
        _add_text(tf, "genrepo/pyproject.toml",
                  '[project]\nname = "genrepo"\nversion = "0.1.0"\n')
        _add_text(tf, "genrepo/src/manual.py",
                  'def my_func():\n    return "handwritten"\n')
        _add_text(tf, "genrepo/src/generated.py",
                  '# Auto-generated by the build system. DO NOT EDIT.\n\n'
                  'class Generated:\n    pass\n')
        _add_text(tf, "genrepo/src/also_generated.go",
                  '// Code generated by tool. DO NOT EDIT.\n\n'
                  'package generated\n\nvar Data = map[string]int{}\n')
    return buf.getvalue()


if __name__ == "__main__":
    base = Path(__file__).parent / "repos"
    base.mkdir(exist_ok=True)

    for name, builder in [
        ("clean_repo.tar.gz", make_clean_repo),
        ("no_tests.tar.gz", make_no_tests_repo),
        ("js_repo.tar.gz", make_js_repo),
        ("generated.tar.gz", make_generated_repo),
    ]:
        data = builder()
        path = base / name
        path.write_bytes(data)
        print(f"Wrote {path} ({len(data)} bytes)")
